import manifest from './albums.json';

// Generated by `npm run photos`; see scripts/process-photos.mjs.
export const home = manifest.albums.find((a) => a.slug === manifest.home);
export const albums = manifest.albums.filter((a) => a.slug !== manifest.home);

export const thumbUrl = (album, photo, w) => `/gallery/${album.slug}/t${w}/${photo.id}.webp`;
export const largeUrl = (album, photo) => `/gallery/${album.slug}/l/${photo.id}.webp`;
export const originalUrl = (album, photo) => `/gallery/${album.slug}/${photo.file}`;
export const splashUrl = (album, w) => `/gallery/${album.slug}/splash-${w}.webp`;
